#[test]
fn test_percent_family_requires_incumbent_support_before_a_crop() {
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let words: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rows: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let plan: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let am: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let bm: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pm: &mut crate::port::Cells = &mut crate::port::Cells::new();
    pctt_words(text, words);
    crate::testport::assert_eq(pct_rows(words, text, 0, 15, rows, am, bm, pm), 5, "five complete geometric rows");
    crate::testport::assert_eq(crate::port::cells_at(rows, 3), 1, "first identity closes on incumbents");
    crate::testport::assert_eq(crate::port::cells_at(rows, 19), 0, "the positive sign fails the negative change");
    crate::testport::assert_eq(pct_plan(words, rows, plan), 4, "one supported failing cell gets a crop");
    crate::testport::assert_eq(crate::port::cells_at(plan, 0), 14, "only the failing percent slot");
    crate::testport::assert_eq(crate::port::cells_at(plan, 2), 4, "four incumbent identities support the family");
    crate::port::cells_set(rows, 3, 0);
    crate::testport::assert_eq(pct_plan(words, rows, plan), 0, "three holds cannot authorize a crop");
}
