fn test_percent_crop_cap_holds_two_independently_supported_failing_slots() {
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let words: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rows: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let proposal: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let am: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let bm: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pm: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mut w: i32 = 15;
    let mut x: i32 = 0;
    pctt_words(text, words);
    pctt_words(text, words);
    while w < 30 {
        x = ow_get(words, w, hd_x0()) + 900;
        ow_set(words, w, hd_x0(), x);
        x = ow_get(words, w, hd_x1()) + 900;
        ow_set(words, w, hd_x1(), x);
        w += 1;
    }
    crate::testport::assert_eq(pct_rows(words, text, 0, 30, rows, am, bm, pm), 10, "two complete five-row families");
    crate::testport::assert_eq(pct_plan(words, rows, proposal), 0, "two separately supported failures exceed this stage's one-crop cap");
    crate::testport::assert_eq(crate::port::cells_len(proposal), 0, "a cap veto leaves no stale proposal");
}
