#[test]
fn test_three_times_crop_filter_preserves_flat_gray_and_central_ink() {
    let bms: &crate::port::BitmapSet = &crate::port::BitmapSet::new();
    let src: &crate::port::Bitmap = crate::port::bms_put(bms, 1, 9, 1, 1);
    let mut x: i32 = 0;
    while x < 9 {
        crate::port::bitmap_set_u8(src, x, 0, 0, 120);
        x += 1;
    }
    oa_three(bms, 2, 3, src);
    let flat: &crate::port::Bitmap = crate::port::bms_get(bms, 2);
    crate::testport::assert_eq(crate::port::bitmap_w(flat), 27, "integer x3 width");
    crate::testport::assert_eq(crate::port::bitmap_h(flat), 3, "integer x3 height");
    crate::testport::assert_eq(crate::port::bitmap_u8(flat, 13, 1, 0), 120, "normalized coefficients preserve flat gray");
    x = 0;
    while x < 9 {
        crate::port::bitmap_set_u8(src, x, 0, 0, 255);
        x += 1;
    }
    crate::port::bitmap_set_u8(src, 4, 0, 0, 0);
    oa_three(bms, 4, 5, src);
    let ink: &crate::port::Bitmap = crate::port::bms_get(bms, 4);
    crate::testport::assert_eq(crate::port::bitmap_u8(ink, 13, 1, 0), 0, "source-center phase preserves black ink");
    crate::testport::assert_eq(crate::port::bitmap_u8(ink, 12, 1, 0), 47, "independent Lanczos sample left of the central stroke");
    crate::testport::assert_eq(crate::port::bitmap_u8(ink, 14, 1, 0), 47, "symmetric sample right of the central stroke");
}
